const cache = { a: 1, b: undefined };

function lookup(key) {
  if (key in cache) {
    return "hit";
  }

  cache[key] = undefined;
  return "miss";
}

console.log(lookup("b"));
console.log(lookup("c"));
console.log(lookup("c"));
console.log(delete cache.a, lookup("a"));
console.log(lookup("toString"));
